def get_components(grid, H, W):
    visited = set()
    comps = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 1 and (r, c) not in visited:
                comp = []
                queue = [(r, c)]

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    comp.append((curr_r, curr_c))

                    # 4-connectivity
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
