def analyze_by_color(grid, H, W):
    visited = set()
    results = {}

    colors = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 1:
                colors.add(grid[r][c])

    print(f"Colors present: {sorted(colors)}")

    for color in sorted(colors):
        positions = [(r,c) for r in range(H) for c in range(W) if grid[r][c] == color]

        # Find connected components for this color
        comp_by_size = {}
        for pos in positions:
            if pos in visited:
                continue

            comp = []
            queue = [pos]

            while queue:
                curr = queue.pop(0)
                if curr in visited:
                    continue
                visited.add(curr)
                comp.append(curr)

                r, c = curr
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if grid[nr][nc] == color and (nr, nc) not in visited:
                            queue.append((nr, nc))

            size = len(comp)
            if size not in comp_by_size:
                comp_by_size[size] = []
            comp_by_size[size].append({'rect': get_rect(comp)})

        print(f"\nColor {color}:")
        for sz in sorted(comp_by_size.keys(), reverse=True):
            print(f"  Size {sz}: {len(comp_by_size[sz])} component(s)")
        print(f"  Total cells: {sum(len(comp_by_size[s]) for s in comp_by_size)}")

def get_rect(comp):
    return (min(p[0] for p in comp), max(p[0] for p in comp), 
            min(p[1] for p in comp), max(p[1] for p in comp))

